sudo awk '
/^\[/{cur=$0}
/^enabled=0$/{ if(cur=="[pgdg15]" || cur=="[pgdg-common]") {print "enabled=1"; next} }
{print}
' /etc/yum.repos.d/pgdg-redhat-all.repo | sudo tee /tmp/pgdg.repo.new >/dev/null
sudo cp /tmp/pgdg.repo.new /etc/yum.repos.d/pgdg-redhat-all.repo
grep -A3 '^\[pgdg15\]$\|^\[pgdg-common\]$' /etc/yum.repos.d/pgdg-redhat-all.repo

